import React from "react";
import {
  AbsoluteFill,
  interpolate,
  interpolateColors,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
// Load closest approximations for requested fonts: Jost (Futura style)
import { makeLoadFont } from '../googleFonts';
const loadJost = makeLoadFont('Jost');

const { fontFamily: jostFamily } = loadJost();



export type BalmToPowderProps = Record<string, any>;

const BalmToPowderAnimation: React.FC<BalmToPowderProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 6,
  mainTextColor = "#4A3B32",
  balmAccentColor = "#D3A78B",
  options = ["Applicator", "Fingers", "Brush"],
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Background ethereal "balm" blobs that fade out into a matte powder finish
  const blobOpacity = interpolate(frame, [0, 100], [0.3, 0], {
    extrapolateRight: "clamp",
  });
  
  const blob1X = interpolate(frame, [0, 150], [width * 0.2, width * 0.5]);
  const blob1Y = interpolate(frame, [0, 150], [height * 0.3, height * 0.1]);
  const blob2X = interpolate(frame, [0, 150], [width * 0.8, width * 0.4]);
  const blob2Y = interpolate(frame, [0, 150], [height * 0.6, height * 0.8]);

  const getIcon = (index: number, color: string, size: number) => {
    return (
      <div
        style={{
          width: size,
          height: size,
          borderRadius: "50%",
          border: `3px solid ${color}`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          flexShrink: 0,
          transition: "none",
        }}
      >
        <div
          style={{
            fontFamily: jostFamily,
            fontSize: size * 0.45,
            fontWeight: 700,
            color: color,
            lineHeight: 1,
            transition: "none",
          }}
        >
          {index + 1}
        </div>
      </div>
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Balm Ambient Background Effect */}
      <div
        style={{
          position: "absolute",
          width: width * 0.5,
          height: width * 0.5,
          borderRadius: "50%",
          backgroundColor: balmAccentColor,
          filter: "blur(140px)",
          opacity: blobOpacity,
          transform: `translate(${blob1X}px, ${blob1Y}px)`,
          transition: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          width: width * 0.6,
          height: width * 0.6,
          borderRadius: "50%",
          backgroundColor: "#FFFFFF",
          filter: "blur(160px)",
          opacity: blobOpacity * 0.8,
          transform: `translate(${blob2X}px, ${blob2Y}px)`,
          transition: "none",
        }}
      />

      {/* Options Layout (Side-by-side Row) */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          display: "flex",
          flexDirection: "row",
          justifyContent: "center",
          alignItems: "center",
          gap: width * 0.08,
          paddingLeft: width * 0.05,
          paddingRight: width * 0.05,
          zIndex: 10,
        }}
      >
        {options.map((text, i) => {
          // Stagger each item's entrance
          const itemStart = 10 + i * 15;

          const itemOpacity = interpolate(
            frame,
            [itemStart, itemStart + 20],
            [0, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );

          const itemY = interpolate(
            frame,
            [itemStart, itemStart + 25],
            [40, 0],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );

          // The "Balm" effect: starts glossy/blurred and colored, resolves to sharp dark "powder"
          const itemBlur = interpolate(
            frame,
            [itemStart, itemStart + 20],
            [20, 0],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );

          const itemColor = interpolateColors(
            frame,
            [itemStart + 10, itemStart + 40],
            [balmAccentColor, mainTextColor]
          );

          return (
            <div
              key={i}
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "flex-start",
                width: width * 0.22,
                opacity: itemOpacity,
                transform: `translateY(${itemY}px)`,
                filter: `blur(${itemBlur}px)`,
                gap: height * 0.04,
                transition: "none",
              }}
            >
              {getIcon(i, itemColor, height * 0.12)}
              <div
                style={{
                  fontFamily: jostFamily,
                  fontSize: height * 0.032,
                  fontWeight: 700,
                  color: itemColor,
                  letterSpacing: "0.15em",
                  textTransform: "uppercase",
                  textAlign: "center",
                  lineHeight: 1.3,
                  transition: "none",
                }}
              >
                {text}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default BalmToPowderAnimation;